// Generated by build.js from src/dexscreener.js - edit that, not this.
var __XCAP_EXTENSION = true;

/**
 * DexScreener chart-endpoint capture.
 * Paste into the DevTools Console on a dexscreener.com pool page.
 *
 * Shows only the pool currently open by default, keeps one entry per pool,
 * pulls token symbol / contract from the pair-details response, and renders
 * a floating panel with copy buttons.
 */
(() => {
    // ─────────────────────────── CONFIG ───────────────────────────
    const CONFIG = {
        // Where the "Open Sheet" button goes. Copy first, then click it.
        sheetUrl: 'https://docs.google.com/spreadsheets/d/1Yk2vMgJEQEidZ0D7EjQMZcRDXwaMghtTQhEMvsOCpsE/edit?gid=808635128#gid=808635128',

        // Open the sheet in this tab (true) or a new one (false).
        sheetSameTab: false
    };
    // ──────────────────────────────────────────────────────────────

    // Installed as an extension, the settings live in chrome.storage, which a
    // MAIN-world script cannot reach - and MAIN world is required, since
    // hooking the page's own fetch is the whole point. bridge.js copies the
    // settings onto the root element instead, and signals when they change.
    function applyStoredConfig() {
        try {
            const raw = document.documentElement.getAttribute('data-xcap-config');
            if (raw) Object.assign(CONFIG, JSON.parse(raw));
        } catch (e) { /* keep the defaults above */ }
    }
    applyStoredConfig();

    // Re-pasting must replace the running build, not stack another set of
    // fetch/XHR wrappers on top of it.
    if (window.__chart) {
        if (!window.__chart.uninstall) {
            console.warn('[chart] an older build is running and cannot be removed - reload the page (F5), then paste again');
            return;
        }
        window.__chart.uninstall();
        console.log('%c[chart] replaced previous build', 'color:#666');
    }

    const RE = /\/dex\/chart\/.*?\/([^\/]+)\/bars\/([^\/]+)\/([^\/?#]+)/;
    const DETAIL_RE = /\/pair-details\//i;
    const MONO = 'ui-monospace,SFMono-Regular,Menlo,Consolas,monospace';
    const SANS = '-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif';

    const CSS_PANEL = 'position:fixed;top:16px;right:16px;z-index:2147483647;width:440px;'
        + 'max-height:82vh;overflow:auto;background:#fff;color:#000;border:2px solid #000;'
        + 'box-shadow:0 8px 32px rgba(0,0,0,.35);font-family:' + SANS + ';font-size:12px;'
        + 'text-align:left;box-sizing:border-box;';
    const CSS_HEAD = 'display:flex;align-items:center;justify-content:space-between;gap:8px;'
        + 'padding:10px 12px;background:#000;color:#fff;cursor:move;position:sticky;top:0;'
        + 'font-size:11px;font-weight:700;letter-spacing:.5px;text-transform:uppercase;';
    const CSS_BTN = 'display:inline-block;padding:5px 10px;background:#000;color:#fff;'
        + 'border:1px solid #000;border-radius:0;font-family:' + SANS + ';font-size:10px;'
        + 'font-weight:700;letter-spacing:.5px;text-transform:uppercase;cursor:pointer;'
        + 'line-height:1;margin:0;box-sizing:border-box;';
    const CSS_VAL = 'margin:3px 0 7px;padding:6px 8px;background:#f5f5f5;border:1px solid #ddd;'
        + 'font-family:' + MONO + ';font-size:10px;line-height:1.45;word-break:break-all;'
        + 'max-height:66px;overflow:auto;';
    const CSS_TAG = 'font-size:9px;font-weight:700;letter-spacing:.5px;color:#666;text-transform:uppercase;';

    // cs is deliberately not here: it is shown in the panel and the JSON, but
    // is not one of the sheet's columns.
    const COLUMNS = ['Symbol', 'ChainID', 'DexID', 'Quote', 'Contract', 'Pool Address'];

    const found = new Map();    // pool identity -> best chart request for that pool
    const seen = [];            // every chart URL, in order
    const details = new Map();  // pool address (lowercased) -> pair-details JSON
    const asked = new Set();
    let detailTemplate = null;  // a real pair-details URL, to model refetches on
    let timer = null;
    let minimized = false;
    let onlyCurrent = true;
    let query = '';

    // dexscreener lowercases the address in its own URL, but base58 pool
    // addresses are case-sensitive, so every comparison is lowercased.
    function currentTarget() {
        const m = location.pathname.match(/^\/([^\/]+)\/([^\/?#]+)/);
        return m ? { chain: m[1].toLowerCase(), pool: m[2].toLowerCase() } : null;
    }
    let target = currentTarget();

    function parse(raw) {
        let u;
        try { u = new URL(raw, location.origin); } catch (e) { return null; }
        const m = u.pathname.match(RE);
        if (!m) return null;

        const q = u.searchParams.get('q') || '';
        const res = u.searchParams.get('res') || '1440';
        const cb = u.searchParams.get('cb') || '2';

        return {
            protocol: m[1],
            chain: m[2],
            poolAddress: m[3],
            quoteToken: q,
            csValue: u.searchParams.get('cs'),
            rawUrl: u.href,
            // drop mc / cs / uo / bbn, blank out abn, keep abn/res/cb/q in order
            cleanedUrl: u.origin + u.pathname + '?abn=&res=' + res + '&cb=' + cb + '&q=' + q,
            hasAbn: u.searchParams.has('abn'),
            cb: parseInt(cb, 10) || 0
        };
    }

    const keyOf = h => [h.protocol, h.chain, h.poolAddress, h.quoteToken].join('|');

    // The initial chart load is the useful one: it carries cs / abn and a low cb.
    // Later requests are pagination (bbn) with a throwaway cb.
    function score(h) {
        return (h.csValue ? 10000 : 0) + (h.hasAbn ? 1000 : 0) - Math.min(h.cb, 999);
    }

    let announce = false;
    const IN_FRAME = window !== window.top;

    function publish(h) {
        if (!h) return;
        const payload = {
            source: 'xcap',
            type: 'chart',
            dexId: (h.protocol || '').toLowerCase(),
            chain: h.chain,
            pool: h.poolAddress,
            quote: h.quoteToken,
            cs: h.csValue || ''
        };
        try { window.parent.postMessage(payload, '*'); } catch (e) { /* ignore */ }
    }

    function add(raw) {
        const hit = parse(raw);
        if (!hit) return;
        seen.push(hit.rawUrl);

        const k = keyOf(hit);
        const prev = found.get(k);
        if (prev && score(prev) >= score(hit)) return;

        found.set(k, hit);
        if (IN_FRAME) publish(hit);
        if (!announce) return;
        clearTimeout(timer);
        timer = setTimeout(() => render(false), 700);
    }

    // Chart bars now fire inside a Web Worker, so wrapping window.fetch is not
    // enough. Hook Worker/SharedWorker at document_start (before DexScreener
    // boots) and also listen for URLs the extension background saw on the wire.
    const OrigWorker = window.Worker;
    const OrigSharedWorker = window.SharedWorker;
    const workerBlobs = [];

    function hrefOf(scriptURL) {
        try {
            if (typeof scriptURL === 'string') return new URL(scriptURL, location.href).href;
            if (scriptURL && typeof scriptURL.href === 'string') {
                return new URL(scriptURL.href, location.href).href;
            }
        } catch (e) { /* fall through */ }
        return String(scriptURL || '');
    }

    function tapPort(target) {
        if (!target || typeof target.addEventListener !== 'function') return;
        target.addEventListener('message', ev => {
            const d = ev.data;
            if (!d || typeof d !== 'object' || !d.__xcapUrl) return;
            try { add(d.__xcapUrl); } catch (e) { /* never break the page */ }
            try { ev.stopImmediatePropagation(); } catch (e) { /* ignore */ }
        }, true);
    }

    function wrapWorkerSource(abs) {
        const hook = [
            '(function(){',
            'var f=self.fetch;',
            'self.fetch=function(){try{var i=arguments[0];var u=typeof i==="string"?i:(i&&i.url)||"";if(u)self.postMessage({__xcapUrl:String(u)})}catch(e){}return f.apply(this,arguments)};',
            'var X=self.XMLHttpRequest;',
            'if(X){var o=X.prototype.open;X.prototype.open=function(m,u){try{if(u)self.postMessage({__xcapUrl:String(u)})}catch(e){}return o.apply(this,arguments)}}',
            '})();',
            'importScripts(' + JSON.stringify(abs) + ');'
        ].join('');
        const blob = new Blob([hook], { type: 'text/javascript' });
        const url = URL.createObjectURL(blob);
        workerBlobs.push(url);
        return url;
    }

    if (OrigWorker) {
        window.Worker = function Worker(scriptURL, options) {
            options = options || {};
            const abs = hrefOf(scriptURL);
            let w;
            // Module workers can't take importScripts. Leave them to webRequest.
            if (options.type === 'module') {
                w = new OrigWorker(scriptURL, options);
            } else {
                try {
                    w = new OrigWorker(wrapWorkerSource(abs), options);
                } catch (e) {
                    w = new OrigWorker(scriptURL, options);
                }
            }
            tapPort(w);
            return w;
        };
        window.Worker.prototype = OrigWorker.prototype;
        Object.defineProperty(window.Worker, 'name', { value: 'Worker' });
    }

    if (OrigSharedWorker) {
        window.SharedWorker = function SharedWorker(scriptURL, options) {
            const abs = hrefOf(scriptURL);
            const opts = typeof options === 'string' ? { name: options } : (options || {});
            let sw;
            if (opts.type === 'module') {
                sw = new OrigSharedWorker(scriptURL, options);
            } else {
                try {
                    sw = new OrigSharedWorker(wrapWorkerSource(abs), opts);
                } catch (e) {
                    sw = new OrigSharedWorker(scriptURL, options);
                }
            }
            tapPort(sw.port);
            try { sw.port.start(); } catch (e) { /* already started */ }
            return sw;
        };
        window.SharedWorker.prototype = OrigSharedWorker.prototype;
    }

    const listAll = () => [...found.values()];
    const filtering = () => onlyCurrent && !!target;
    const onPage = () => (filtering()
        ? listAll().filter(h => h.poolAddress.toLowerCase() === target.pool)
        : listAll());
    const list = () => applyQuery(onPage());

    // What a typed query is matched against, and the shorthands accepted.
    const QUERY_ALIASES = {
        sym: 'symbol', ticker: 'symbol',
        chain: 'chain', net: 'chain',
        dex: 'dexid', protocol: 'dexid', dexid: 'dexid',
        addr: 'contract', address: 'contract', ca: 'contract',
        pool: 'pool', pair: 'pool',
        quote: 'quote', q: 'quote'
    };

    function applyQuery(rows) {
        const match = makeMatcher(query, QUERY_ALIASES);
        if (!match) return rows;
        return rows.filter(h => {
            const m = metaOf(h);
            return match({
                symbol: (m.symbol || '').toLowerCase(),
                contract: (m.contract || '').toLowerCase(),
                chain: (h.chain || '').toLowerCase(),
                dexid: (h.protocol || '').toLowerCase(),
                pool: (h.poolAddress || '').toLowerCase(),
                quote: (h.quoteToken || '').toLowerCase(),
                cs: (h.csValue || '').toLowerCase()
            });
        });
    }

    // ---- pair-details: symbol and contract address ----------------------
    //
    // The chart endpoint carries neither, so they come from the pair-details
    // response. Its shape is undocumented, so keys are matched by pattern
    // rather than hardcoded.

    function walk(root, visit) {
        const queue = [root];
        let steps = 0;
        while (queue.length && steps++ < 20000) {
            const node = queue.shift();
            if (!node || typeof node !== 'object') continue;
            for (const k of Object.keys(node)) {
                let v;
                try { v = node[k]; } catch (e) { continue; }
                if (visit(k, v, node) === true) return true;
                if (v && typeof v === 'object') queue.push(v);
            }
        }
        return false;
    }

    const isStr = v => typeof v === 'string' && v.trim() !== '';

    // Breadth-first, so the shallowest match wins.
    function findKey(root, re, ok) {
        let hit = null;
        walk(root, (k, v) => {
            if (re.test(k) && ok(v)) { hit = { key: k, value: v }; return true; }
            return false;
        });
        return hit;
    }

    // The path version has moved before (v3 -> v4), so a guess is tried only
    // after the shape the page itself used, and newest-first after that.
    function detailUrls(chain, pool) {
        const urls = [];
        if (detailTemplate) {
            try {
                const u = new URL(detailTemplate);
                const parts = u.pathname.split('/').filter(Boolean);
                parts[parts.length - 1] = pool;
                if (parts.length >= 2) parts[parts.length - 2] = chain;
                urls.push(u.origin + '/' + parts.join('/'));
            } catch (e) { /* fall through to the guesses */ }
        }
        const env = window.__DS_ENV || {};
        const host = env.DS_WEB_PAIR_DETAILS_SERVER_HOST || 'https://io.dexscreener.com';
        ['v4', 'v3'].forEach(v => urls.push(host + '/dex/pair-details/' + v + '/' + chain + '/' + pool));
        return [...new Set(urls)];
    }

    function poolFromDetailUrl(raw) {
        try {
            const parts = new URL(raw, location.origin).pathname.split('/').filter(Boolean);
            return (parts[parts.length - 1] || '').toLowerCase();
        } catch (e) { return null; }
    }

    function saveDetails(url, json) {
        const pool = poolFromDetailUrl(url);
        if (!pool || !json) return;
        detailTemplate = url;
        details.set(pool, json);
        clearTimeout(timer);
        timer = setTimeout(() => render(false), 200);
    }

    // The page fetches pair-details on load, usually before this script is
    // pasted, so the body is already gone. Ask for it again in that case.
    function wantDetails(h) {
        const pool = h.poolAddress.toLowerCase();
        if (details.has(pool) || asked.has(pool)) return;
        asked.add(pool);

        const candidates = detailUrls(h.chain, h.poolAddress);
        (function attempt(i) {
            if (i >= candidates.length) {
                console.warn('[chart] no pair-details for ' + h.poolAddress
                    + ' - symbol and contract will stay blank. Tried:\n' + candidates.join('\n'));
                return;
            }
            const url = candidates[i];
            origFetch.call(window, url, { credentials: 'omit' })
                .then(r => (r.ok ? r.json() : null))
                .then(j => { if (j) saveDetails(url, j); else attempt(i + 1); })
                .catch(() => attempt(i + 1));
        })(0);
    }

    const SYMBOL_KEYS = ['symbol', 'sym', 'tokenSymbol'];
    const ADDRESS_KEYS = ['address', 'addr', 'tokenAddress', 'mint', 'contract'];
    const pickKey = (obj, keys) => {
        for (const k of keys) if (isStr(obj[k])) return obj[k];
        return '';
    };

    // Any object carrying both a symbol and an address is a token. The one
    // that is neither the pool nor the quote token is the base token - which
    // holds regardless of what the surrounding keys are called.
    function findBaseToken(d, poolAddress, quoteToken) {
        const skip = new Set([poolAddress.toLowerCase(), (quoteToken || '').toLowerCase()]);
        let hit = null;
        walk(d, (k, v) => {
            if (!v || typeof v !== 'object' || Array.isArray(v)) return false;
            const symbol = pickKey(v, SYMBOL_KEYS);
            const address = pickKey(v, ADDRESS_KEYS);
            if (!symbol || !address || skip.has(address.toLowerCase())) return false;
            hit = { symbol, address };
            return true;   // breadth-first, so the shallowest token wins
        });
        return hit;
    }

    function metaOf(h) {
        const d = details.get(h.poolAddress.toLowerCase());
        const out = { symbol: '', contract: '', pending: !d };
        if (!d) return out;

        // an explicit baseToken is the most trustworthy answer
        let base = null;
        walk(d, (k, v) => {
            if (/^base_?token$/i.test(k) && v && typeof v === 'object') { base = v; return true; }
            return false;
        });
        if (base) {
            out.symbol = pickKey(base, SYMBOL_KEYS);
            out.contract = pickKey(base, ADDRESS_KEYS);
        }

        if (!out.symbol || !out.contract) {
            const guess = findBaseToken(d, h.poolAddress, h.quoteToken);
            if (guess) {
                out.symbol = out.symbol || guess.symbol;
                out.contract = out.contract || guess.address;
            }
        }

        if (!out.symbol) {
            const s = findKey(d, /^(baseTokenSymbol|baseSymbol)$/i, isStr);
            if (s) out.symbol = s.value;
        }
        if (!out.contract) {
            const a = findKey(d, /^(baseTokenAddress|tokenAddress)$/i, isStr);
            if (a) out.contract = a.value;
        }
        return out;
    }

    const jsonOf = h => {
        const m = metaOf(h);
        return JSON.stringify({
            symbol: m.symbol || null,
            chain: h.chain,
            contractAddress: m.contract || null,
            protocol: h.protocol,
            poolAddress: h.poolAddress,
            quoteToken: h.quoteToken,
            csValue: h.csValue
        }, null, 2);
    };

    // Symbol / ChainID / DexID / Quote / Contract / Pool Address
    const tsvOf = h => {
        const m = metaOf(h);
        return [m.symbol, h.chain, h.protocol, h.quoteToken,
            m.contract, h.poolAddress].join('\t');
    };

    // ---- ui kit ------------------------------------------------------------
    //
    // Shared by both capture scripts; build.js splices this in where each one
    // says @@UI_KIT@@, so the two panels cannot drift apart visually.
    //
    // Icons are Lucide (ISC licence), inlined as path data. They cannot be
    // imported: MV3 forbids remote code, and a content script drawing into the
    // page is bound by that page's CSP either way, so a CDN link or a sprite
    // sheet would simply fail to load.

    const ICONS = {
        grip: '<circle cx="9" cy="6" r="1"/><circle cx="15" cy="6" r="1"/>'
            + '<circle cx="9" cy="12" r="1"/><circle cx="15" cy="12" r="1"/>'
            + '<circle cx="9" cy="18" r="1"/><circle cx="15" cy="18" r="1"/>',
        copy: '<rect width="14" height="14" x="8" y="8" rx="2" ry="2"/>'
            + '<path d="M4 16c-1.1 0-2-.9-2-2V4c0-1.1.9-2 2-2h10c1.1 0 2 .9 2 2"/>',
        check: '<path d="M20 6 9 17l-5-5"/>',
        x: '<path d="M18 6 6 18"/><path d="m6 6 12 12"/>',
        minus: '<path d="M5 12h14"/>',
        plus: '<path d="M5 12h14"/><path d="M12 5v14"/>',
        refresh: '<path d="M3 12a9 9 0 0 1 9-9 9.75 9.75 0 0 1 6.74 2.74L21 8"/>'
            + '<path d="M21 3v5h-5"/>'
            + '<path d="M21 12a9 9 0 0 1-9 9 9.75 9.75 0 0 1-6.74-2.74L3 16"/>'
            + '<path d="M3 21v-5h5"/>',
        filter: '<polygon points="22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3"/>',
        layers: '<path d="m12.83 2.18a2 2 0 0 0-1.66 0L2.6 6.08a1 1 0 0 0 0 1.83l8.58 3.91a2 2 0 0 0 1.66 0l8.58-3.9a1 1 0 0 0 0-1.83Z"/>'
            + '<path d="m22 17.65-9.17 4.16a2 2 0 0 1-1.66 0L2 17.65"/>'
            + '<path d="m22 12.65-9.17 4.16a2 2 0 0 1-1.66 0L2 12.65"/>',
        sheet: '<rect width="18" height="18" x="3" y="3" rx="2" ry="2"/>'
            + '<line x1="3" x2="21" y1="9" y2="9"/><line x1="3" x2="21" y1="15" y2="15"/>'
            + '<line x1="9" x2="9" y1="9" y2="21"/><line x1="15" x2="15" y1="9" y2="21"/>',
        braces: '<path d="M8 3H7a2 2 0 0 0-2 2v5a2 2 0 0 1-2 2 2 2 0 0 1 2 2v5c0 1.1.9 2 2 2h1"/>'
            + '<path d="M16 21h1a2 2 0 0 0 2-2v-5c0-1.1.9-2 2-2a2 2 0 0 1-2-2V5a2 2 0 0 0-2-2h-1"/>',
        trash: '<path d="M3 6h18"/><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"/>'
            + '<path d="M8 6V4c0-1 1-2 2-2h4c1 0 2 1 2 2v2"/>',
        link: '<path d="M15 3h6v6"/><path d="M10 14 21 3"/>'
            + '<path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/>',
        alert: '<path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3"/>'
            + '<path d="M12 9v4"/><path d="M12 17h.01"/>',
        search: '<circle cx="11" cy="11" r="8"/><path d="m21 21-4.3-4.3"/>',
        scan: '<path d="M3 7V5a2 2 0 0 1 2-2h2"/><path d="M17 3h2a2 2 0 0 1 2 2v2"/>'
            + '<path d="M21 17v2a2 2 0 0 1-2 2h-2"/><path d="M7 21H5a2 2 0 0 1-2-2v-2"/>'
            + '<path d="M7 12h10"/>'
    };

    const SVG_NS = 'http://www.w3.org/2000/svg';

    function icon(name, size) {
        const svg = document.createElementNS(SVG_NS, 'svg');
        svg.setAttribute('viewBox', '0 0 24 24');
        svg.setAttribute('width', size || 14);
        svg.setAttribute('height', size || 14);
        svg.setAttribute('fill', 'none');
        svg.setAttribute('stroke', 'currentColor');
        svg.setAttribute('stroke-width', '2');
        svg.setAttribute('stroke-linecap', 'round');
        svg.setAttribute('stroke-linejoin', 'round');
        svg.setAttribute('aria-hidden', 'true');
        svg.innerHTML = ICONS[name] || '';
        return svg;
    }

    // The panel lives in a shadow root, so the host page's stylesheets cannot
    // reach it and this can be a real stylesheet rather than inline styles on
    // every element.
    const THEME = `
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    .panel {
        --sans: ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
        --mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace;
        --bg: #0a0a0a;
        --bg-head: #0a0a0a;
        --bg-sub: #141414;
        --line: #2a2a2c;
        --line-soft: #2a2a2c;
        --fg: #f4f4f5;
        --fg-dim: #8b8b90;
        --fg-faint: #636369;
        font-family: var(--sans);
        font-size: 13px;
        line-height: 1.5;
        color: var(--fg);
        background: var(--bg);
        border: none;
        border-radius: 24px;
        box-shadow: 0 0 0 1px rgba(255,255,255,.08), 0 24px 64px rgba(0,0,0,.55);
        display: flex;
        flex-direction: column;
        max-height: 84vh;
        overflow: hidden;
    }
    .head {
        display: flex; align-items: center; gap: 8px;
        padding: 9px 10px;
        background: var(--bg-head);
        border-bottom: 1px solid var(--line);
        cursor: grab; user-select: none; flex: 0 0 auto;
    }
    .head:active { cursor: grabbing; }
    .head .grip { color: var(--fg-faint); flex: 0 0 auto; display: flex; }
    .title {
        font-size: 13px; font-weight: 500; letter-spacing: 0; text-transform: none;
        color: var(--fg); white-space: nowrap;
    }
    .count {
        font-size: 12px; color: var(--fg-dim);
        padding: 0; min-width: 0; text-align: left; border: none;
    }
    .spacer { flex: 1 1 auto; }
    .tools { display: flex; gap: 4px; flex: 0 0 auto; }

    button {
        font-family: var(--sans); font-size: 13px; color: inherit;
        background: none; border: 1px solid transparent; border-radius: 999px;
        cursor: pointer; display: inline-flex; align-items: center; justify-content: center;
    }
    .ibtn {
        width: 36px; height: 36px; color: var(--fg-dim);
        border-color: transparent; transition: color .12s, background .12s;
    }
    .ibtn:hover { color: var(--fg); background: #1c1c1c; }
    .ibtn.on { color: #0a0a0a; background: var(--fg); }

    .strip {
        display: flex; align-items: center; gap: 6px;
        padding: 6px 10px; background: var(--bg-sub);
        border-bottom: 1px solid var(--line-soft);
        font-size: 11px; color: var(--fg-dim); flex: 0 0 auto;
    }
    .strip .k { color: var(--fg); }
    .strip svg { flex: 0 0 auto; color: var(--fg-faint); }

    .search {
        display: flex; align-items: center; gap: 8px;
        margin: 8px 10px; padding: 0 12px; height: 40px; flex: 0 0 auto;
        background: #141414; border: none; border-radius: 999px;
        box-shadow: 0 0 0 1px rgba(255,255,255,.08);
    }
    .search svg { color: var(--fg-faint); flex: 0 0 auto; }
    .search input {
        flex: 1 1 auto; min-width: 0; height: 100%;
        background: none; border: none; outline: none;
        font-family: var(--sans); font-size: 13px; color: var(--fg);
    }
    .search input::placeholder { color: var(--fg-faint); }
    .search .hits {
        flex: 0 0 auto; font-size: 10px; color: var(--fg-faint);
        font-variant-numeric: tabular-nums;
    }
    .search .clear {
        flex: 0 0 auto; width: 20px; height: 20px; color: var(--fg-faint);
    }
    .search .clear:hover { color: var(--fg); }
    .search:focus-within { background: #0f0f13; }
    .search:focus-within svg { color: var(--fg-dim); }

    .body { overflow: auto; flex: 1 1 auto; }
    .body::-webkit-scrollbar { width: 10px; height: 10px; }
    .body::-webkit-scrollbar-thumb { background: #26262b; border: 3px solid var(--bg); }
    .body::-webkit-scrollbar-track { background: var(--bg); }

    table { width: 100%; border-collapse: collapse; }
    thead th {
        position: sticky; top: 0; z-index: 1;
        background: var(--bg-sub);
        padding: 6px 10px; text-align: left;
        font-size: 11px; font-weight: 500; letter-spacing: 0; text-transform: none;
        color: var(--fg-dim);
        border-bottom: 1px solid var(--line);
        white-space: nowrap;
    }
    tbody td {
        padding: 8px 10px; vertical-align: middle;
        border-bottom: 1px solid var(--line-soft);
        font-size: 12px;
    }
    tbody tr:hover td { background: #141418; }
    tbody tr:last-child td { border-bottom: none; }
    td.num { text-align: right; color: var(--fg-dim); font-variant-numeric: tabular-nums; }
    td.act { width: 34px; text-align: right; padding-left: 0; }

    .token { display: flex; align-items: center; gap: 8px; min-width: 0; }
    .token img {
        width: 18px; height: 18px; border-radius: 50%;
        background: #1a1a1e; flex: 0 0 auto;
    }
    .token .names { min-width: 0; overflow: hidden; }
    .token .sym { font-weight: 700; letter-spacing: .02em; white-space: nowrap; }
    .token .sub {
        font-size: 10px; color: var(--fg-faint); letter-spacing: .04em;
        white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
    }
    tbody td:first-child { min-width: 132px; }
    .clip { display: block; max-width: 220px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-family: var(--mono); font-size: 11px; }
    .dim { color: var(--fg-dim); }
    .faint { color: var(--fg-faint); }

    .rows { padding: 2px 0; }
    .field { padding: 8px 10px; border-bottom: 1px solid var(--line-soft); }
    .field .lab {
        display: flex; align-items: center; justify-content: space-between; gap: 8px;
        font-size: 11px; letter-spacing: 0; text-transform: none; color: var(--fg-dim);
        margin-bottom: 5px;
    }
    .field .val {
        background: #141414; border: none; border-radius: 12px;
        padding: 8px 10px; font-size: 11px; line-height: 1.55;
        font-family: var(--mono);
        word-break: break-all; max-height: 72px; overflow: auto; color: var(--fg);
        box-shadow: 0 0 0 1px rgba(255,255,255,.08);
    }
    .kv { display: flex; gap: 10px; padding: 4px 0; font-size: 12px; align-items: flex-start; }
    .kv .k { flex: 0 0 72px; color: var(--fg-dim); padding-top: 1px; }
    .kv .v { flex: 1 1 auto; word-break: break-all; font-family: var(--mono); font-size: 11px; }

    .foot {
        flex: 0 0 auto; border-top: 1px solid var(--line);
        background: #141414; padding: 10px; display: flex; flex-direction: column; gap: 6px;
    }
    .bar { display: flex; gap: 6px; }
    .tbtn {
        flex: 1 1 0; gap: 6px; height: 36px; padding: 0 12px;
        border-color: transparent; color: var(--fg); background: #1c1c1c;
        letter-spacing: 0; text-transform: none; font-size: 13px; font-weight: 500;
        transition: color .12s, background .12s;
        box-shadow: 0 0 0 1px rgba(255,255,255,.08);
    }
    .tbtn:hover { color: var(--fg); background: #242424; }
    .tbtn.primary { background: var(--fg); color: #0a0a0a; box-shadow: none; }
    .tbtn.primary:hover { background: #fff; }
    .tbtn.narrow { flex: 0 0 auto; width: 36px; padding: 0; }
    .tbtn.ok { color: #0a0a0a; background: var(--fg); }

    .hint { padding: 8px 10px 10px; font-size: 10px; line-height: 1.7; color: var(--fg-faint); }
    .empty {
        padding: 22px 16px; text-align: center; color: var(--fg-dim);
        font-size: 12px; line-height: 1.7;
    }
    .empty svg { color: var(--fg-faint); margin-bottom: 8px; }
    `;

    // One host element carrying a shadow root. Returned on later calls so the
    // panel keeps its position across re-renders.
    function shell(id, width) {
        const existing = document.getElementById(id);
        if (existing && existing.__ui) return existing.__ui;

        const host = document.createElement('div');
        host.id = id;
        host.style.cssText = 'position:fixed;top:16px;right:16px;z-index:2147483647;'
            + 'width:' + (width || 460) + 'px;max-width:calc(100vw - 32px);';

        const root = host.attachShadow({ mode: 'open' });
        const style = document.createElement('style');
        style.textContent = THEME;
        root.appendChild(style);

        const panel = document.createElement('div');
        panel.className = 'panel';
        root.appendChild(panel);

        host.__ui = { host: host, root: root, panel: panel };
        document.documentElement.appendChild(host);
        return host.__ui;
    }

    function el(tag, cls, text) {
        const n = document.createElement(tag);
        if (cls) n.className = cls;
        if (text != null) n.textContent = text;
        return n;
    }

    function iconBtn(name, title, fn, extraClass) {
        const b = el('button', 'ibtn' + (extraClass ? ' ' + extraClass : ''));
        b.title = title;
        b.appendChild(icon(name, 14));
        b.onclick = e => { e.stopPropagation(); fn(); };
        return b;
    }

    function textBtn(label, iconName, title, fn, extraClass) {
        const b = el('button', 'tbtn' + (extraClass ? ' ' + extraClass : ''));
        if (title) b.title = title;
        if (iconName) b.appendChild(icon(iconName, 13));
        const span = el('span', null, label);
        b.appendChild(span);
        b.__label = span;
        b.__icon = iconName;
        b.onclick = e => { e.stopPropagation(); fn(b); };
        return b;
    }

    // Swaps the label and icon for a moment, then puts them back.
    function feedback(button, text, iconName, ok) {
        if (!button || !button.__label) return;
        const label = button.__label.textContent;
        const original = button.__icon;
        button.__label.textContent = text;
        if (button.firstChild && button.firstChild.tagName === 'svg') {
            button.replaceChild(icon(iconName, 13), button.firstChild);
        }
        button.classList.toggle('ok', !!ok);
        setTimeout(() => {
            button.__label.textContent = label;
            if (original && button.firstChild && button.firstChild.tagName === 'svg') {
                button.replaceChild(icon(original, 13), button.firstChild);
            }
            button.classList.remove('ok');
        }, 1400);
    }

    function emptyState(iconName, text) {
        const wrap = el('div', 'empty');
        wrap.appendChild(icon(iconName, 22));
        wrap.appendChild(el('div', null, text));
        return wrap;
    }

    // ---- query -------------------------------------------------------------
    //
    // Plain words match any field; field:value narrows to one. Several terms all
    // have to match, so "sol usdc" and "chain:solana pump" both work.

    function parseQuery(text) {
        return String(text || '').trim().toLowerCase().split(/\s+/)
            .filter(Boolean)
            .map(term => {
                const colon = term.indexOf(':');
                return colon > 0
                    ? { key: term.slice(0, colon), value: term.slice(colon + 1) }
                    : { key: null, value: term };
            })
            .filter(term => term.value);
    }

    // aliases maps what a person might type to the field name the row uses.
    // exact names the fields where a digits-only term means that exact number:
    // substring matching on an id makes "ucid:1" match 1041 as well as 1.
    function makeMatcher(text, aliases, exact) {
        const terms = parseQuery(text);
        if (!terms.length) return null;
        const exactly = exact || {};

        const hit = (key, value, fields) => {
            const field = fields[key];
            if (field == null) return false;
            if (exactly[key] && /^\d+$/.test(value)) return field === value;
            return field.indexOf(value) !== -1;
        };

        return fields => terms.every(term => {
            if (!term.key) {
                for (const key in fields) if (hit(key, term.value, fields)) return true;
                return false;
            }
            const key = aliases[term.key] || term.key;
            // an unknown field name would otherwise match everything
            if (!(key in fields)) return false;
            return hit(key, term.value, fields);
        });
    }

    // The input is kept alive across row repaints - rebuilding it would take the
    // caret with it on every keystroke.
    function searchBox(state, onChange) {
        const wrap = el('div', 'search');
        wrap.appendChild(icon('search', 13));

        const input = document.createElement('input');
        input.type = 'text';
        input.value = state.query || '';
        input.placeholder = state.placeholder || 'filter…';
        input.spellcheck = false;
        input.addEventListener('input', () => onChange(input.value));
        input.addEventListener('keydown', e => {
            e.stopPropagation();   // the host page has its own shortcuts
            if (e.key === 'Escape' && input.value) { input.value = ''; onChange(''); }
        });
        wrap.appendChild(input);

        const hits = el('span', 'hits');
        wrap.appendChild(hits);

        const clear = iconBtn('x', 'Clear the filter', () => {
            input.value = '';
            onChange('');
            input.focus();
        }, 'clear');
        wrap.appendChild(clear);

        return {
            el: wrap,
            input: input,
            // shown only while filtering, so an unfiltered panel stays quiet
            update: (shown, total) => {
                const filtering = !!input.value;
                hits.textContent = filtering ? shown + '/' + total : '';
                clear.style.visibility = filtering ? 'visible' : 'hidden';
            }
        };
    }

    // ---- clipboard ---------------------------------------------------------

    function writeClipboard(text) {
        if (navigator.clipboard && navigator.clipboard.writeText) {
            return navigator.clipboard.writeText(text).catch(() => execCopy(text));
        }
        return execCopy(text);
    }

    // Covers browsers without the async API, and the "document is not focused"
    // rejection that follows focus moving to a newly opened tab.
    function execCopy(text) {
        return new Promise((resolve, reject) => {
            const ta = document.createElement('textarea');
            ta.value = text;
            ta.style.cssText = 'position:fixed;top:-2000px;left:-2000px;opacity:0';
            document.body.appendChild(ta);
            ta.select();
            let ok = false;
            try { ok = document.execCommand('copy'); } catch (e) { ok = false; }
            ta.remove();
            if (ok) resolve(); else reject(new Error('copy failed'));
        });
    }

    function copyBtn(label, iconName, title, getText, extraClass) {
        return textBtn(label, iconName, title, button => {
            writeClipboard(getText()).then(
                () => feedback(button, 'Copied', 'check', true),
                () => feedback(button, 'Failed', 'alert', false)
            );
        }, extraClass);
    }

    function copyIconBtn(title, getText) {
        const b = iconBtn('copy', title, () => {
            writeClipboard(getText()).then(() => {
                b.replaceChild(icon('check', 14), b.firstChild);
                b.classList.add('on');
                setTimeout(() => {
                    b.replaceChild(icon('copy', 14), b.firstChild);
                    b.classList.remove('on');
                }, 1200);
            }, () => {
                b.replaceChild(icon('alert', 14), b.firstChild);
                setTimeout(() => b.replaceChild(icon('copy', 14), b.firstChild), 1400);
            });
        });
        return b;
    }

    // Dragging moves the host, which is what carries the fixed position.
    function draggable(handle, host) {
        handle.onmousedown = e => {
            if (e.target.closest('button')) return;
            e.preventDefault();
            const r = host.getBoundingClientRect();
            const dx = e.clientX - r.left;
            const dy = e.clientY - r.top;
            const move = ev => {
                host.style.left = (ev.clientX - dx) + 'px';
                host.style.top = (ev.clientY - dy) + 'px';
                host.style.right = 'auto';
            };
            const up = () => {
                document.removeEventListener('mousemove', move);
                document.removeEventListener('mouseup', up);
            };
            document.addEventListener('mousemove', move);
            document.addEventListener('mouseup', up);
        };
    }

    function header(ui, title, count, tools) {
        const head = el('div', 'head');
        const grip = el('span', 'grip');
        grip.appendChild(icon('grip', 14));
        head.appendChild(grip);
        head.appendChild(el('span', 'title', title));
        head.appendChild(el('span', 'count', String(count)));
        head.appendChild(el('span', 'spacer'));
        const box = el('span', 'tools');
        tools.forEach(t => box.appendChild(t));
        head.appendChild(box);
        draggable(head, ui.host);
        return head;
    }


    // ---- sheet ----------------------------------------------------------

    function openSheet() {
        if (!CONFIG.sheetUrl) {
            console.warn('[chart] no sheetUrl set - open the extension popup, or edit CONFIG above');
            return;
        }
        if (CONFIG.sheetSameTab) location.href = CONFIG.sheetUrl;
        else window.open(CONFIG.sheetUrl, '_blank', 'noopener');
    }

    // One click, both jobs. Order matters twice over: a popup blocker rejects
    // window.open once an await has broken the chain back to the click, and
    // navigating this tab away cancels a copy still in flight.
    function copyAndOpenSheet(text, button) {
        const done = writeClipboard(text);
        if (CONFIG.sheetSameTab) done.then(openSheet, openSheet);
        else openSheet();
        done.then(
            () => feedback(button, 'Copied', 'check', true),
            () => feedback(button, 'Failed', 'alert', false)
        );
        return done;
    }

    // ---- panel ----------------------------------------------------------

    const PANEL_ID = '__chart_panel';

    function kv(label, value, dim) {
        const row = el('div', 'kv');
        row.appendChild(el('span', 'k', label));
        row.appendChild(el('span', 'v' + (dim ? ' dim' : ''), value || '—'));
        return row;
    }

    function urlField(label, value) {
        const wrap = el('div', 'field');
        const head = el('div', 'lab');
        head.appendChild(el('span', null, label));
        head.appendChild(copyIconBtn('Copy ' + label, () => value));
        wrap.appendChild(head);
        wrap.appendChild(el('div', 'val', value));
        return wrap;
    }

    function card(h) {
        wantDetails(h);   // lazy: only pools actually on screen are looked up
        const m = metaOf(h);
        const c = el('div', 'rows');

        const head = el('div', 'field');
        const token = el('div', 'token');
        const names = el('div', 'names');
        names.appendChild(el('div', 'sym', m.symbol || h.protocol));
        names.appendChild(el('div', 'sub', h.protocol + '  ·  ' + h.chain));
        token.appendChild(names);
        head.appendChild(token);

        const info = el('div');
        info.style.marginTop = '8px';
        info.appendChild(kv('Contract', m.contract || (m.pending ? 'loading…' : ''), !m.contract));
        info.appendChild(kv('Pool', h.poolAddress));
        info.appendChild(kv('Quote', h.quoteToken));
        info.appendChild(kv('cs', h.csValue, true));
        head.appendChild(info);
        c.appendChild(head);

        c.appendChild(urlField('Raw URL', h.rawUrl));
        c.appendChild(urlField('Cleaned URL', h.cleanedUrl));

        const bar = el('div', 'bar');
        bar.style.padding = '10px';
        bar.appendChild(copyBtn('TSV', 'sheet',
            'Tab-separated:\n' + COLUMNS.join(' / '), () => tsvOf(h)));
        bar.appendChild(copyBtn('JSON', 'braces', 'This pool as JSON', () => jsonOf(h)));
        c.appendChild(bar);

        return c;
    }

    // force: open the panel even with nothing captured, as feedback that a
    // hand-pasted script installed. Installed, it waits until it has
    // something to show rather than sitting on every page.
    function render(force) {
        if (IN_FRAME) return;
        const onPageRows = onPage();
        const rows = applyQuery(onPageRows);
        const hidden = listAll().length - onPageRows.length;

        const existing = document.getElementById(PANEL_ID);
        let ui = existing && existing.__ui;
        if (!ui) {
            if (!onPageRows.length && !force) return;
            ui = shell(PANEL_ID, 450);
        }
        const panel = ui.panel;
        panel.textContent = '';

        const head = header(ui, 'Chart Endpoints', rows.length, [
            iconBtn('refresh', 'Scan again — replay requests already on the page',
                () => { armCapture(); render(true); }),
            iconBtn(filtering() ? 'filter' : 'layers',
                filtering() ? 'This pool only — click to show every pool captured'
                    : 'Every pool captured — click to filter to this page',
                () => { onlyCurrent = !onlyCurrent; render(true); },
                filtering() ? 'on' : ''),
            iconBtn(minimized ? 'plus' : 'minus', minimized ? 'Expand' : 'Collapse',
                () => { minimized = !minimized; render(true); }),
            iconBtn('x', 'Close', () => ui.host.remove())
        ]);
        panel.appendChild(head);
        const headCount = head.querySelector('.count');

        if (minimized) return;

        const strip = el('div', 'strip');
        strip.appendChild(icon(filtering() ? 'filter' : 'layers', 12));
        if (filtering()) {
            strip.appendChild(el('span', 'k', target.pool));
            if (hidden) strip.appendChild(el('span', 'faint', '· ' + hidden + ' hidden'));
        } else {
            strip.appendChild(el('span', null,
                target ? 'every pool captured' : 'not a pool page — everything captured'));
        }
        panel.appendChild(strip);

        const body = el('div', 'body');

        // Typing repaints the rows only. Rebuilding the whole panel would
        // recreate the input and take the caret with it on every keystroke.
        const search = searchBox(
            { query: query, placeholder: 'filter…  wif  ·  dex:uniswap  ·  chain:base' },
            value => {
                query = value;
                const shown = applyQuery(onPage());
                paint(body, shown);
                headCount.textContent = String(shown.length);
                search.update(shown.length, onPageRows.length);
            });
        panel.appendChild(search.el);
        panel.appendChild(body);

        paint(body, rows);
        search.update(rows.length, onPageRows.length);

        const foot = el('div', 'foot');

        const copyBar = el('div', 'bar');
        copyBar.appendChild(copyBtn('All TSV', 'sheet',
            'Tab-separated, one row per pool:\n' + COLUMNS.join(' / '),
            () => visible().map(tsvOf).join('\n')));
        copyBar.appendChild(copyBtn('All URLs', 'link', 'Every cleaned URL shown, one per line',
            () => visible().map(h => h.cleanedUrl).join('\n')));
        foot.appendChild(copyBar);

        const goBar = el('div', 'bar');
        goBar.appendChild(textBtn('Copy + Open Sheet', 'link',
            'Copies every row shown, then opens the sheet — just paste:\n'
            + (CONFIG.sheetUrl || '(no sheet URL set)'),
            b => copyAndOpenSheet(visible().map(tsvOf).join('\n'), b), 'primary'));
        goBar.appendChild(textBtn('', 'trash', 'Clear everything captured',
            () => { found.clear(); seen.length = 0; query = ''; render(true); }, 'narrow'));
        foot.appendChild(goBar);

        panel.appendChild(foot);
        panel.appendChild(el('div', 'hint', 'TSV columns — ' + COLUMNS.join(' · ')));
    }

    // The copy buttons follow the filter: what is on screen is what is copied.
    function visible() {
        return applyQuery(onPage());
    }

    function paint(body, rows) {
        body.textContent = '';
        if (!rows.length) {
            body.appendChild(emptyState(query ? 'search' : 'scan', query
                ? 'Nothing matches that filter.'
                : 'Nothing captured yet. Press Scan, then switch timeframe (1m / 5m / 1D) if the chart request already fired.'));
            return;
        }
        rows.forEach(h => body.appendChild(card(h)));
    }

    function show() {
        if (IN_FRAME) return;
        const all = list();
        render();
        if (!all.length) {
            console.warn('[chart] ยังไม่เจอ - ลองสลับ timeframe หรือ reload');
            return;
        }
        console.log('%c CHART ENDPOINTS (' + all.length + ') ',
            'background:#000;color:#fff;font-weight:bold;padding:2px 6px');
        all.forEach((h, i) => {
            const m = metaOf(h);
            console.group('%c' + (i + 1) + '. ' + (m.symbol || h.protocol) + '%c  ' + h.poolAddress,
                'color:#000;font-weight:bold', 'color:#666');
            console.log('%cRAW    ', 'color:#999', h.rawUrl);
            console.log('%cCLEANED', 'color:#000;font-weight:bold', h.cleanedUrl);
            console.log('%cJSON', 'color:#999', '\n' + jsonOf(h));
            console.groupEnd();
        });
        const hidden = listAll().length - all.length;
        if (hidden) {
            console.log('%c(' + hidden + ' other pools hidden - __chart.showAll() to include them)', 'color:#999');
        }
    }

    // dexscreener navigates without reloading, so the page pool can change
    // under a panel that is already open.
    function onNav() {
        setTimeout(() => { target = currentTarget(); render(); }, 0);
    }
    const origPush = history.pushState;
    const origReplace = history.replaceState;
    history.pushState = function (...a) { const r = origPush.apply(this, a); onNav(); return r; };
    history.replaceState = function (...a) { const r = origReplace.apply(this, a); onNav(); return r; };
    window.addEventListener('popstate', onNav);

    // Captured up front so armCapture / wantDetails can call the real fetch.
    const origFetch = window.fetch;
    const origOpen = XMLHttpRequest.prototype.open;
    const origSend = XMLHttpRequest.prototype.send;
    let captureArmed = false;

    function replayResources() {
        try {
            performance.getEntriesByType('resource').forEach(e => {
                if (DETAIL_RE.test(e.name)) detailTemplate = e.name;
                add(e.name);
            });
        } catch (e) { /* resource timing unavailable */ }
    }

    function armCapture() {
        if (captureArmed) {
            replayResources();
            return;
        }
        captureArmed = true;

        // 1. requests that already fired. Only the URLs survive here.
        replayResources();

        // 2. future fetch()
        window.fetch = function (...args) {
            const i = args[0];
            let url = '';
            try { url = typeof i === 'string' ? i : (i && i.url) || String(i); } catch (e) { /* opaque input */ }
            try { add(url); } catch (e) { /* never break the page */ }
            const p = origFetch.apply(this, args);
            if (url && DETAIL_RE.test(url)) {
                try {
                    p.then(r => { r.clone().json().then(j => saveDetails(url, j), () => {}); }, () => {});
                } catch (e) { /* never break the page */ }
            }
            return p;
        };

        // 3. future XMLHttpRequest
        XMLHttpRequest.prototype.open = function (method, url, ...rest) {
            try { add(url); this.__chartUrl = url; } catch (e) { /* never break the page */ }
            return origOpen.call(this, method, url, ...rest);
        };
        XMLHttpRequest.prototype.send = function (...a) {
            try {
                const u = this.__chartUrl;
                if (u && DETAIL_RE.test(u)) {
                    this.addEventListener('load', () => {
                        try { saveDetails(u, JSON.parse(this.responseText)); } catch (e) { /* not JSON */ }
                    });
                }
            } catch (e) { /* never break the page */ }
            return origSend.apply(this, a);
        };
    }

    // The popup's Show Panel button and any settings change arrive as plain
    // DOM events, the only channel the two worlds share.
    const onStoredConfig = () => {
        applyStoredConfig();
        if (document.getElementById('__chart_panel')) render(false);
    };
    function requestScan() {
        announce = true;
        armCapture();
        render(true);
        if (found.size) show();
        else console.log('%c[chart] listening%c  switch timeframe if the chart request already expired',
            'color:#000;font-weight:bold', 'color:#666');
    }
    const onShowRequest = () => { requestScan(); };
    const onNet = ev => { try { add(ev.detail); } catch (e) { /* ignore */ } };
    document.addEventListener('xcap:config', onStoredConfig);
    document.addEventListener('xcap:show', onShowRequest);
    document.addEventListener('xcap:net', onNet);

    function uninstall() {
        document.removeEventListener('xcap:config', onStoredConfig);
        document.removeEventListener('xcap:show', onShowRequest);
        document.removeEventListener('xcap:net', onNet);
        clearTimeout(timer);
        window.fetch = origFetch;
        XMLHttpRequest.prototype.open = origOpen;
        XMLHttpRequest.prototype.send = origSend;
        if (OrigWorker) window.Worker = OrigWorker;
        if (OrigSharedWorker) window.SharedWorker = OrigSharedWorker;
        workerBlobs.forEach(u => { try { URL.revokeObjectURL(u); } catch (e) { /* ignore */ } });
        history.pushState = origPush;
        history.replaceState = origReplace;
        window.removeEventListener('popstate', onNav);
        const p = document.getElementById('__chart_panel');
        if (p) p.remove();
        delete window.__chart;
    }

    window.__chart = {
        show, list, uninstall,
        pools: listAll,
        all: () => [...seen],
        columns: () => COLUMNS.slice(),
        config: CONFIG,
        openSheet,
        copyAndOpen: () => copyAndOpenSheet(list().map(tsvOf).join('\n')),
        // the pair-details URLs that would be tried, in order
        detailUrls: () => list().map(h => detailUrls(h.chain, h.poolAddress)),
        // raw pair-details JSON, for checking what the site actually returned
        details: pool => pool
            ? details.get(String(pool).toLowerCase())
            : Object.fromEntries(details),
        meta: () => list().map(metaOf),
        showAll: () => { onlyCurrent = false; show(); },
        showCurrent: () => { onlyCurrent = true; show(); },
        json: () => {
            const a = list().map(h => JSON.parse(jsonOf(h)));
            return JSON.stringify(a.length === 1 ? a[0] : a, null, 2);
        },
        // tab-separated, one row per pool - paste straight into Google Sheets
        sheets: () => list().map(tsvOf).join('\n'),
        tsv: () => list().map(tsvOf).join('\n'),
        clean: () => list().map(h => h.cleanedUrl).join('\n'),
        raw: () => list().map(h => h.rawUrl).join('\n'),
        reset: () => { found.clear(); seen.length = 0; details.clear(); asked.clear(); render(); }
    };

    // Tampermonkey defines GM_info even under @grant none, and the extension
    // build defines its own flag. Either way: installed rather than pasted, so
    // the panel waits until it has something to show.
    const AUTO = typeof GM_info !== 'undefined'
        || (typeof __XCAP_EXTENSION !== 'undefined' && __XCAP_EXTENSION);

    // Installed: do not wrap fetch or open the panel until Scan.
    // Pasted into the console: arm immediately so the paste is visible.
    if (IN_FRAME) requestScan();
    else if (!AUTO) requestScan();
    else console.log('%c[chart] ready%c  press Scan in the toolbar popup'
        + (target ? '  pool: ' + target.pool : ''),
        'color:#000;font-weight:bold', 'color:#666');
})();
